// ============================================================
// MAIN SEED FUNCTION
// ============================================================
async function main() {
  console.log("🌱 Seeding Asgari Tour & Travels database...")

  // Clean
  await db.packageCoupon.deleteMany()
  await db.packageDestination.deleteMany()
  await db.coupon.deleteMany()
  await db.tourPackage.deleteMany()
  await db.activity.deleteMany()
  await db.destination.deleteMany()
  await db.blogPost.deleteMany()
  await db.lead.deleteMany()
  await db.testimonial.deleteMany()
  await db.googleReview.deleteMany()
  await db.galleryImage.deleteMany()
  await db.seoPage.deleteMany()
  await db.siteSetting.deleteMany()
  await db.hostingerLog.deleteMany()

  // Destinations
  console.log("📍 Seeding Kashmir destinations...")
  for (const d of kashmirDestinations) {
    await db.destination.create({
      data: {
        ...d,
        region: "kashmir",
        images: "[]",
        thingsToDo: JSON.stringify(d.thingsToDo),
        status: "published",
      } as any,
    })
  }
  console.log("📍 Seeding Ladakh destinations...")
  for (const d of ladakhDestinations) {
    await db.destination.create({
      data: {
        ...d,
        region: "ladakh",
        images: "[]",
        thingsToDo: JSON.stringify(d.thingsToDo),
        status: "published",
      } as any,
    })
  }

  // Packages
  console.log("📦 Seeding tour packages...")
  for (const p of packages) {
    const { destinations: destSlugs, ...pkg } = p
    const created = await db.tourPackage.create({
      data: {
        ...pkg,
        images: "[]",
        coverImage: null,
        inclusions: JSON.stringify(pkg.inclusions),
        exclusions: JSON.stringify(pkg.exclusions),
        highlights: JSON.stringify(pkg.highlights),
        itinerary: JSON.stringify(pkg.itinerary),
        status: "published",
      } as any,
    })
    // Link destinations
    for (let i = 0; i < destSlugs.length; i++) {
      const dest = await db.destination.findUnique({ where: { slug: destSlugs[i] } })
      if (dest) {
        await db.packageDestination.create({
          data: { packageId: created.id, destinationId: dest.id, order: i },
        })
      }
    }
  }

  // Coupons
  console.log("🎟️ Seeding coupons...")
  for (const c of coupons) {
    await db.coupon.create({ data: c as any })
  }

  // Blog posts
  console.log("✍️ Seeding blog posts...")
  for (const b of blogPosts) {
    await db.blogPost.create({
      data: {
        ...b,
        tags: JSON.stringify(b.tags),
        coverImage: null,
        status: "published",
      } as any,
    })
  }

  // Testimonials
  console.log("⭐ Seeding testimonials...")
  for (const t of testimonials) {
    await db.testimonial.create({ data: { ...t, avatar: null, packageId: null } as any })
  }

  // Google reviews
  console.log("🔍 Seeding google reviews...")
  for (const r of googleReviews) {
    await db.googleReview.create({
      data: { ...r, reviewDate: new Date(), placeId: null } as any,
    })
  }

  // SEO pages
  console.log("📄 Seeding SEO pages...")
  for (const s of seoPages) {
    await db.seoPage.create({
      data: { ...s, sections: "[]", heroImage: null, status: "published" } as any,
    })
  }

  // Site settings
  console.log("⚙️ Seeding site settings...")
  for (const s of siteSettings) {
    await db.siteSetting.create({ data: s as any })
  }

  console.log("✅ Seed complete!")
  console.log(`   ${kashmirDestinations.length} Kashmir destinations`)
  console.log(`   ${ladakhDestinations.length} Ladakh destinations`)
  console.log(`   ${packages.length} tour packages`)
  console.log(`   ${blogPosts.length} blog posts`)
  console.log(`   ${testimonials.length} testimonials`)
  console.log(`   ${coupons.length} coupons`)
  console.log(`   ${seoPages.length} SEO pages`)
  console.log(`   ${siteSettings.length} site settings`)
}

main()
  .catch((e) => {
    console.error(e)
    process.exit(1)
  })
  .finally(async () => {
    await db.$disconnect()
  })
